1: /**
2:  * ResonanceReefs — audio-reactive coral shelves ringing the dream archipelago.
3:  *
4:  * Vector 2 of the living-systems brief: "generative spatial Web Audio drives the
5:  * 3D landscape topology". The soundscape is the instrument; the reefs are its
6:  * resonating body. Loud passages bloom the coral, quiet passages let it settle,
7:  * and pulses of light travel outward across a shelf like sound through water.
8:  *
9:  * Lifecycle follows the host contract:
10:  *   const reefs = new ResonanceReefs(scene, camera, renderer);
11:  *   reefs.update(elapsedTime);   // once per frame
12:  *
13:  * The host publishes audio energy through `reefBus` (a tiny shared channel) so
14:  * the module stays decoupled from the game's Web Audio graph.
15:  */
16: import * as THREE from 'three';
17: 
18: /** Shared channel: the host writes, this module reads. */
19: export const reefBus = {
20:   level: 0,      // smoothed 0..1 audio energy
21:   beat: 0,       // rises on transients, decays on its own
22:   hue: 0,        // 0..1 colour drift supplied by the ecosystem
23: };
24: 
25: const TAU = Math.PI * 2;
26: const rand = (a, b) => a + Math.random() * (b - a);
27: const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
28: 
29: /** One coral shelf: a ring of instanced fronds anchored on the sea floor. */
30: class Shelf {
31:   constructor(opts) {
32:     this.cx = opts.x;
33:     this.cz = opts.z;
34:     this.radius = opts.radius;
35:     this.count = opts.count;
36:     this.phase = opts.phase;
37:     this.hue = opts.hue;
38:     this.bloom = 0;
39:     this.bloomTarget = 0;
40:     this.pulse = -1;          // seconds since the last pulse fired (<0 = idle)
41:     this.pulsePeriod = rand(3.5, 9);
42:     this.fronds = [];
43:     for (let i = 0; i < this.count; i++) {
44:       const a = (i / this.count) * TAU + rand(-0.12, 0.12);
45:       const r = this.radius * rand(0.72, 1.05);
46:       this.fronds.push({
47:         x: this.cx + Math.cos(a) * r,
48:         z: this.cz + Math.sin(a) * r,
49:         // outward-facing so pulses read as a wave travelling across the shelf
50:         dir: a,
51:         h: rand(1.4, 3.4),
52:         w: rand(0.2, 0.42),
53:         lean: rand(-0.22, 0.22),
54:         sway: rand(0.6, 1.7),
55:         seed: rand(0, TAU),
56:         grow: rand(0, 1),      // 0..1 boot-in
57:       });
58:     }
59:   }
60: }
61: 
62: /** Soft radial sprite texture, generated locally so the module stays self-contained. */
63: function makeGlowTexture() {
64:   const c = document.createElement('canvas');
65:   c.width = c.height = 128;
66:   const ctx = c.getContext('2d');
67:   const g = ctx.createRadialGradient(64, 64, 2, 64, 64, 64);
68:   g.addColorStop(0, 'rgba(255,255,255,0.95)');
69:   g.addColorStop(0.35, 'rgba(94,234,212,0.45)');
70:   g.addColorStop(0.7, 'rgba(45,212,191,0.14)');
71:   g.addColorStop(1, 'rgba(45,212,191,0)');
72:   ctx.fillStyle = g;
73:   ctx.fillRect(0, 0, 128, 128);
74:   return new THREE.CanvasTexture(c);
75: }
