77: export class ResonanceReefs {
78:   constructor(scene, camera, renderer, options = {}) {
79:     this.scene = scene;
80:     this.camera = camera;
81:     this.renderer = renderer;
82: 
83:     this.enabled = options.enabled !== false;
84:     this.quality = options.quality || 'high';
85: 
86:     this.group = new THREE.Group();
87:     this.group.name = 'ResonanceReefs';
88:     scene.add(this.group);
89: 
90:     this.shelves = [];
91:     this._t = 0;
92:     this._smoothLevel = 0;
93:     this._beatPrev = 0;
94: 
95:     this._build();
96:   }
97: 
98:   /** Frond geometry: a tapered cone reads as kelp/coral at low poly counts. */
99:   _makeGeometry() {
100:     const g = new THREE.ConeGeometry(0.5, 1, 5, 1, true);
101:     g.translate(0, 0.5, 0);   // grow from the base, not the centre
102:     return g;
103:   }
104: 
105:   _build() {
106:     const per = { low: 26, mid: 44, high: 64 }[this.quality] || 64;
107:     const shelfCount = { low: 3, mid: 5, high: 7 }[this.quality] || 7;
108: 
109:     this.material = new THREE.MeshStandardMaterial({
110:       color: 0x1f6f6b,
111:       emissive: 0x0d4f52,
112:       emissiveIntensity: 0.6,
113:       roughness: 0.75,
114:       metalness: 0.05,
115:       flatShading: true,
116:       side: THREE.DoubleSide,
117:       transparent: true,
118:       opacity: 0.94,
119:     });
120: 
121:     this.mesh = new THREE.InstancedMesh(this._makeGeometry(), this.material, per * shelfCount);
122:     this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
123:     this.mesh.frustumCulled = false;
124:     this.mesh.castShadow = false;
125:     this.mesh.receiveShadow = false;
126:     if ('instanceColor' in this.mesh || true) {
127:       // instanceColor is allocated lazily by three when first set
128:       this.mesh.instanceColor = null;
129:     }
130:     this.group.add(this.mesh);
131: 
132:     this.perShelf = per;
133:     this.total = per * shelfCount;
134: 
135:     // Scatter shelves around the archipelago. Positions are authored relative to
136:     // the host's island ring so reefs hug the shorelines without touching land.
137:     const ringRadius = 26;
138:     for (let s = 0; s < shelfCount; s++) {
139:       const a = (s / shelfCount) * TAU + rand(-0.2, 0.2);
140:       const r = ringRadius + rand(-4, 12);
141:       const shelf = new Shelf({
142:         x: Math.cos(a) * r,
143:         z: Math.sin(a) * r,
144:         radius: rand(7, 13),
145:         count: per,
146:         phase: rand(0, TAU),
147:         hue: rand(0.42, 0.58),
148:       });
149:       this.shelves.push(shelf);
150:     }
151: 
152:     // A soft caustic glow disc under each shelf sells the "underwater" read.
153:     this.glowTex = makeGlowTexture();
154:     this.glowMat = new THREE.SpriteMaterial({
155:       map: this.glowTex,
156:       color: 0x2dd4bf,
157:       transparent: true,
158:       opacity: 0.16,
159:       depthWrite: false,
160:       blending: THREE.AdditiveBlending,
161:     });
162:     this.glows = this.shelves.map((s) => {
163:       const sp = new THREE.Sprite(this.glowMat.clone());
164:       sp.position.set(s.cx, -0.95, s.cz);
165:       sp.scale.set(s.radius * 2.4, s.radius * 2.4, 1);
166:       this.group.add(sp);
167:       return sp;
168:     });
169: 
170:     this._m = new THREE.Matrix4();
171:     this._q = new THREE.Quaternion();
172:     this._e = new THREE.Euler();
173:     this._v = new THREE.Vector3();
174:     this._s = new THREE.Vector3();
175:     this._c = new THREE.Color();
176:     this._eulers = this.shelves.map(() => new THREE.Euler());
177:   }
178: 
179:   /** Public: host can reposition reefs when the archipelago changes. */
180:   setAnchors(anchors) {
181:     if (!Array.isArray(anchors) || !anchors.length) return;
182:     this.shelves.forEach((s, i) => {
183:       const a = anchors[i % anchors.length];
184:       if (!a) return;
185:       const dx = a.x - s.cx;
186:       const dz = a.z - s.cz;
187:       s.cx += dx;
188:       s.cz += dz;
189:       s.fronds.forEach((f) => {
190:         f.x += dx;
191:         f.z += dz;
192:       });
193:       if (this.glows[i]) this.glows[i].position.set(s.cx, -0.95, s.cz);
194:     });
195:   }
196: 
197:   setQuality(q) {
198:     if (!['low', 'mid', 'high'].includes(q) || q === this.quality) return;
199:     // Rebuild at the new density rather than thrashing the instance buffer.
200:     this.group.clear();
201:     this.quality = q;
202:     this._build();
203:   }
204: 
205:   setEnabled(on) {
206:     this.enabled = !!on;
207:     this.group.visible = this.enabled;
208:   }
209: 
210:   /**
211:    * Per-frame update.
212:    * @param {number} elapsedTime seconds since start
213:    */
214:   update(elapsedTime) {
215:     if (!this.enabled) return;
216:     const dt = this._last === undefined ? 0 : clamp(elapsedTime - this._last, 0, 0.1);
217:     this._last = elapsedTime;
218:     this._t = elapsedTime;
219: 
220:     // --- consume the host's audio channel -------------------------------
221:     const raw = clamp(reefBus.level || 0, 0, 1);
222:     // asymmetric smoothing: snap up on a hit, ease down on a release
223:     this._smoothLevel += (raw - this._smoothLevel) * (raw > this._smoothLevel ? 0.45 : 0.08);
224:     const energy = this._smoothLevel;
225: 
226:     const beat = reefBus.beat || 0;
227:     if (beat > this._beatPrev + 0.05) {
228:       // transient: fire a pulse from the loudest shelf
229:       let best = this.shelves[0];
230:       let bestE = -1;
231:       for (const s of this.shelves) {
232:         const d = this._cameraEnergy(s);
233:         if (d < bestE) { bestE = d; best = s; }
234:       }
235:       if (best) best.pulse = 0;
236:       this._beatPrev = beat;
237:     }
238: 
239:     // --- drive every frond ----------------------------------------------
240:     let i = 0;
241:     for (const shelf of this.shelves) {
242:       shelf.bloomTarget = energy;
243:       shelf.bloom += (shelf.bloomTarget - shelf.bloom) * Math.min(1, dt * 3.2 + 0.02);
244: 
245:       // travel the pulse outward from the shelf's centre
246:       let wave = 0;
247:       if (shelf.pulse >= 0) {
248:         shelf.pulse += dt;
249:         if (shelf.pulse > 2.6) shelf.pulse = -1;
250:       }
251:       const pulseT = shelf.pulse >= 0 ? shelf.pulse / 2.6 : -1;
252: 
253:       for (const f of shelf.fronds) {
254:         if (f.grow < 1) f.grow = Math.min(1, f.grow + dt * 0.55);
255: 
256:         // radial distance from the shelf centre, normalised 0..1
257:         const rx = f.x - shelf.cx;
258:         const rz = f.z - shelf.cz;
259:         const radial = clamp(Math.hypot(rx, rz) / (shelf.radius * 1.1), 0, 1);
260:         if (pulseT >= 0) {
261:           // gaussian ring riding outward
262:           const d = radial - pulseT;
263:           wave = Math.exp(-d * d * 42) * (1 - pulseT);
264:         }
265: 
266:         const breathe = Math.sin(elapsedTime * f.sway + f.seed) * 0.06;
267:         const swell = 1 + shelf.bloom * 0.85 + wave * 1.25;
268:         const h = f.h * f.grow * swell;
269:         const w = f.w * f.grow * (1 + wave * 0.55);
270: 
271:         // lean away from the shelf centre + current sway
272:         const lean = f.lean + breathe + wave * 0.5;
273:         this._e.set(Math.sin(f.dir) * lean, f.dir, Math.cos(f.dir) * lean, 'YXZ');
274:         this._q.setFromEuler(this._e);
275: 
276:         this._v.set(f.x, -0.95, f.z);
277:         this._s.set(w, h, w);
278:         this._m.compose(this._v, this._q, this._s);
279:         this.mesh.setMatrixAt(i, this._m);
280: 
281:         // hue drifts with the ecosystem; emissive tracks the bloom
282:         const hue = (shelf.hue + (reefBus.hue || 0) * 0.25) % 1;
283:         this._c.setHSL(hue, 0.62, 0.32 + shelf.bloom * 0.18 + wave * 0.4);
284:         this._c.offsetHSL(0, 0, 0);
285:         this.mesh.setColorAt(i, this._c);
286:         i++;
287:       }
288: 
289:       if (this.glows[this.shelves.indexOf(shelf)]) {
290:         const g = this.glows[this.shelves.indexOf(shelf)];
291:         g.material.opacity = 0.12 + shelf.bloom * 0.26 + wave * 0.34;
292:         const s = shelf.radius * (2.2 + wave * 0.5);
293:         g.scale.set(s, s, 1);
294:       }
295:     }
296: 
297:     this.mesh.count = i;
298:     this.mesh.instanceMatrix.needsUpdate = true;
299:     if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
300:     this.material.emissiveIntensity = 0.35 + energy * 1.5;
301:   }
302: 
303:   /** Louder shelves pulse; used to pick which reef answers a transient. */
304:   _cameraEnergy(shelf) {
305:     if (!this.camera) return 0;
306:     const dx = shelf.cx - this.camera.position.x;
307:     const dz = shelf.cz - this.camera.position.z;
308:     return dx * dx + dz * dz;
309:   }
310: 
311:   dispose() {
312:     this.group.traverse((o) => {
313:       if (o.isMesh || o.isSprite) {
314:         if (o.geometry) o.geometry.dispose();
315:         if (o.material) {
316:           (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => m.dispose());
317:         }
318:       }
319:     });
320:     this.scene.remove(this.group);
321:     this.group.clear();
322:   }
323: }
324: 
325: export default ResonanceReefs;

