572: let AC=null, soundOn=true;
573: function ac(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){return null;}}
574:   if(AC.state==='suspended')AC.resume().catch(()=>{});return AC;}
575: function blip(f=520,d=.18,type='sine',g=.16){if(!soundOn)return;try{const c=ac();if(!c)return;const o=c.createOscillator(),v=c.createGain();o.type=type;o.frequency.setValueAtTime(f,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(60,f*.5),c.currentTime+d);v.gain.setValueAtTime(g,c.currentTime);v.gain.exponentialRampToValueAtTime(.0001,c.currentTime+d);o.connect(v).connect(c.destination);o.start();o.stop(c.currentTime+d);}catch(e){}}
