636: /* ============ islands ============ */
637: const dreamGroup=new THREE.Group(); scene.add(dreamGroup); // all player/loom creations
638: const islands=[];
639: function noiseH(x,z){return Math.sin(x*.35)*Math.cos(z*.3)*1.2+Math.sin(x*.12+z*.21)*1.8;}
640: const TOP_Y=1.35;
641: // height of an island's walkable surface (shared by geometry + collision so they never disagree)
642: function islandH(x,z){return TOP_Y+Math.max(0,noiseH(x,z)*.12);}
643: function makeIsland(x,z,r,colorTop=0x7ddf8e,colorSide=0x8a6a4f){
644:   // cliff walls: top rim sits BELOW the lowest walkable height so nothing z-fights
645:   const geo=new THREE.CylinderGeometry(r,r*1.15,7,44,1);
646:   const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:colorSide,roughness:.92}));
647:   m.position.set(x,TOP_Y-.16-3.5,z);m.receiveShadow=true;m.castShadow=true;scene.add(m);
648:   // walkable surface as a radial grid sampling islandH() — visual and collision agree
649:   const RINGS=9,SEG=44,pos=[],idx=[];
650:   pos.push(x,islandH(x,z),z);                       // centre vertex
651:   for(let ri=1;ri<=RINGS;ri++){
652:     const rr=r*.995*(ri/RINGS);
653:     for(let si=0;si<SEG;si++){
654:       const a=si/SEG*Math.PI*2, px=Math.cos(a)*rr, pz=Math.sin(a)*rr;
655:       pos.push(x+px,islandH(x+px,z+pz),z+pz);
656:     }
657:   }
658:   // wind counter-clockwise seen from above so normals face +Y
659:   for(let si=0;si<SEG;si++){const a=1+si,b=1+(si+1)%SEG;idx.push(0,b,a);}
660:   for(let ri=1;ri<RINGS;ri++){
661:     const base=1+(ri-1)*SEG, next=1+ri*SEG;
662:     for(let si=0;si<SEG;si++){
663:       const s2=(si+1)%SEG;
664:       idx.push(base+si,base+s2,next+si, base+s2,next+s2,next+si);
665:     }
666:   }
667:   const tg=new THREE.BufferGeometry();
668:   tg.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
669:   tg.setIndex(idx);tg.computeVertexNormals();
670:   const top=new THREE.Mesh(tg,new THREE.MeshStandardMaterial({color:colorTop,roughness:.85,flatShading:false}));
671:   top.receiveShadow=true;top.castShadow=true;scene.add(top);
672:   // beach rim tucked under the surface edge
673:   const rim=new THREE.Mesh(new THREE.TorusGeometry(r*.99,.5,10,44),
674:     new THREE.MeshStandardMaterial({color:0xfde68a,roughness:.85}));
675:   rim.rotation.x=Math.PI/2;rim.position.set(x,TOP_Y-.2,z);scene.add(rim);
676:   islands.push({x,z,r,topY:TOP_Y});
677:   islandTops.push(top);
678:   return {base:m,top};
679: }
680: const islandTops=[];
681: makeIsland(0,0,22,0x86efac);
682: makeIsland(44,-18,14,0xf9a8d4);
683: makeIsland(-42,-24,15,0x93c5fd);
684: makeIsland(-8,-58,17,0xfde68a);
685: makeIsland(30,42,13,0xc4b5fd);
686: makeIsland(-36,38,12,0x6ee7b7);
687: // walkable height with a soft shoreline so you slide into the sea instead of cliff-dropping
688: function groundY(x,z){
689:   let best=null,bd=1e9;
690:   for(const isl of islands){const d=Math.hypot(x-isl.x,z-isl.z);if(d<bd){bd=d;best=isl;}}
691:   if(best&&bd<best.r){const edge=clamp((best.r-bd)/2.2,0,1);return -1.2+(islandH(x,z)+1.2)*edge;}
692:   return -1.2;
693: }
