 *
 * Pure logic; no DOM, three.js, or game imports. The host supplies:
 *   - actions: callbacks that actually perform each action
 *   - context: a snapshot of the sandbox each tick
 *
 * The engine decides *what* Loom wants to do, learns preferences from the
 * player's behaviour, and returns a small result object for the HUD.
 */

export const DREAM_LIBRARY = [...];

export const TRAITS = {...};

const clamp = ...

const COOLDOWN = { tidy: 16, dream: 0, scout: 34, tend: 26, excavate: 55, swarm: 50 };

const MODE_LABEL = {...}

const INSIGHT_STEPS = [12, 28, 48, 74, 106, 144, 188, 238, 294, 356];

export class LoomAutonomy {
  constructor({actions={}, onLevelUp=null}={}) {
    this.actions = actions;
    this.onLevelUp = onLevelUp;
    this.auto = true;
    this._clock = 0;
    this._nextPlan = 2.5;
    this._cooldowns = {};
    this._lastDream = -999;
    this._lastFocus = -999;
    this.level = 1;
    this.insights = 0;
    this.prefs = {};
    this.traits = {};
    this.seen = new Set();
    this.islandAffinity = {};
    this.tutored = {cozy:0,wild:0,glow:0,nature:0,sky:0};
    this.stats = {playerDreams:0, remixes:0, pets:0, banished:0, autoDreams:0, tidies:0, tended:0, scouted:0, excavations:0, swarm:0, decisions:0, cleaned:0};
    this.journal = [];
    this.drives = {curiosity:.5, order:.2, care:.4};
    this.thought = 'Reading the sandbox…';
    this.mode = 'observing';
    this.lastClutter = 0;
    this.lastTidiness = 1;
  }

  restore(data) {...}
