`observeDream`:
```
observeDream({fn, island, byLoom=false}={}) {
 if(!fn) return;
 if(byLoom){ this.stats.autoDreams++; return; }
 this.stats.playerDreams++;
 this.seen.add(fn);
 this._pref(fn).seen++;
 this._reward(fn, 1.15);
 if(Number.isInteger(island)) this.islandAffinity[island]=(this.islandAffinity[island]||0)+.35;
 this._gainInsight(.9);
}
