`_reward`:
```
_pref(fn){ return this.prefs[fn] ||= {seen:0,love:0,last:0}; }
_reward(fn, amount){
 const p=this._pref(fn); p.love=clamp(p.love+amount,-4,12); p.last=Date.now();
 const meta=DREAM_META[fn]; if(meta){ for(const tag of meta.tags) this.traits[tag]=(this.traits[tag]||0)+amount; }
