`loomTidy(mode='auto')`:
```
let cleaned=0; const parts=[];
const deep=mode==='deep';
// lint first
const lintTarget=deep?dreamLint.length:Math.min(dreamLint.length, Math.max(0,Math.ceil(dreamLint.length*.7)));
for(...) {remove...; cleaned++;} if(n)parts.push(`${n} dream-lint`);
// echoes
const echoes=selectable.filter(g=>g.userData.isEcho).sort((a,b)=>(a.userData.createdAt||0)-(b.userData.createdAt||0));
const echoKeep=deep?1:4;
while(echoes.length>echoKeep){removeDream(echoes.shift(),false);cleaned++;}
// auto dreams
const autos=selectable.filter(g=>g.userData.byLoom&&!g.userData.isEcho).sort(...);
const autoKeep=deep?5:10;
...
// planks
