while(bridgePlanks.length>plankKeep){removePlank(bridgePlanks.shift());cleaned++;}
// flora trim
const floraKeep=Math.floor(FLORA_MAX*(deep?.82:.92));
if(flora.length>floraKeep){const n=flora.length-floraKeep; flora.splice(0,n); cleaned+=n; parts.push(...)}
...
markShadowDirty(2); saveDreams(); stats.loomTidies++; updateStatus(); renderEcoPane? maybe no, panel.
const p=loom.position.clone().add(new THREE.Vector3(0,1.5,0)); burst(p,0x67e8f9,20);
if(cleaned) return {ok:true,cleaned,message:`Tidied ${parts.join(', ')}.`,speech:pick([...]),thought:...};
