/* ============================================================
   LOOM'S AUTONOMY · learned taste, sandbox stewardship, cleanup
   ============================================================ */
let loomRoam=null;
const dreamLint=[];
let lintTimer=8;

function spawnLint(n=1){
  for(let k=0;k<n;k++){
    if(dreamLint.length>=18)return;
    const isl=islands[Math.floor(Math.random()*islands.length)]||islands[0];
    if(!isl)return;
    const x=isl.x+rand(-isl.r*.82,isl.r*.82),z=isl.z+rand(-isl.r*.82,isl.r*.82);
    const m=new THREE.Mesh(new THREE.TetrahedronGeometry(rand(.12,.22),0),
      new THREE.MeshBasicMaterial({color:pick([0x67e8f9,0xa78bfa,0xf9a8d4,0xfde68a]),transparent:true,opacity:.9}));
    m.position.set(x,groundY(x,z)+rand(.35,1.25),z);
    m.userData.lint=true;m.userData.phase=rand(0,6.28);m.userData.spin=rand(-1.6,1.6);
    scene.add(m);dreamLint.push(m);
  }
}
function updateLint(dt,t){
  lintTimer-=dt;
  if(lintTimer<=0&&$('#intro').classList.contains('hide')){
    lintTimer=rand(9,16);spawnLint(Math.random()<.28?2:1);
  }
  for(const m of dreamLint){
    m.rotation.y+=dt*.9;m.rotation.x+=dt*.35;
    m.position.y+=Math.sin(t*1.7+m.userData.phase)*dt*.08;
  }
}
function removeLint(m){
  scene.remove(m);
  if(m.geometry)m.geometry.dispose();
  if(m.material)m.material.dispose();
  const i=dreamLint.indexOf(m);if(i>-1)dreamLint.splice(i,1);
}
function measureClutter(){
  const echoes=selectable.filter(g=>g.userData.isEcho).length;
  const autos=selectable.filter(g=>g.userData.byLoom&&!g.userData.isEcho).length;
  const planks=bridgePlanks.length;
  const lint=dreamLint.length;
  const floraLoad=flora.length/Math.max(1,FLORA_MAX);
  const total=selectable.length;
  const removable=Math.max(0,echoes-3)+Math.max(0,autos-8)+Math.max(0,planks-10)+lint
    +Math.max(0,flora.length-Math.floor(FLORA_MAX*.9));
  const score=clamp(
    Math.max(0,echoes-3)*.07+Math.max(0,autos-8)*.07+Math.max(0,planks-10)*.04
    +lint*.045+Math.max(0,floraLoad-.88)*1.2+Math.max(0,total-26)*.035,0,1);
  return {score,removable,echoes,autos,planks,lint,flora:flora.length,floraMax:FLORA_MAX,total};
}
function removeDreamObject(g,dispose){
  if(!g)return false;
  const p=g.position.clone().add(new THREE.Vector3(0,.8,0));
  if(dispose&&!g.userData.sharedResources){
    g.traverse(o=>{if(o.isMesh||o.isPoints||o.isLine){
      if(o.geometry)o.geometry.dispose();
      if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose&&m.dispose());}});
  }
  dreamGroup.remove(g);
  const i=selectable.indexOf(g);if(i>-1)selectable.splice(i,1);
  if(selected===g)deselect();
  burst(p,0xa5f3fc,8);
  return true;
}
function removePlankRecord(b){
  if(!b||!b.mesh)return false;
  const m=b.mesh;
  m.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material&&o.material.dispose)o.material.dispose();});
  dreamGroup.remove(m);
  const i=selectable.indexOf(m);if(i>-1)selectable.splice(i,1);
  const j=bridgePlanks.indexOf(b);if(j>-1)bridgePlanks.splice(j,1);
  burst(m.position.clone().add(new THREE.Vector3(0,.6,0)),0x67e8f9,7);
  return true;
}
function loomTidy(mode='auto'){
  const deep=mode==='deep';
  let cleaned=0;const parts=[];

  const lintTake=deep?dreamLint.length:Math.ceil(dreamLint.length*.7);
  if(lintTake>0){while(dreamLint.length&&lintTake>dreamLint.length?false:dreamLint.length>0&&(parts.lintTaken||0)<lintTake){removeLint(dreamLint[0]);cleaned++;parts.lintTaken=(parts.lintTaken||0)+1;}}
  if(parts.lintTaken)parts.push(parts.lintTaken+' dream-lint');

  const echoes=selectable.filter(g=>g.userData.isEcho).sort((a,b)=>(a.userData.createdAt||0)-(b.userData.createdAt||0));
  const echoKeep=deep?1:4;let nEcho=0;
  while(echoes.length>echoKeep){removeDreamObject(echoes.shift(),false);cleaned++;nEcho++;}
  if(nEcho)parts.push(nEcho+' echo copies');

  const autos=selectable.filter(g=>g.userData.byLoom&&!g.userData.isEcho).sort((a,b)=>(a.userData.createdAt||0)-(b.userData.createdAt||0));
  const autoKeep=deep?5:10;let nAuto=0;
  while(autos.length>autoKeep){removeDreamObject(autos.shift(),true);cleaned++;nAuto++;}
  if(nAuto)parts.push(nAuto+' old loom-dreams');

  if(swarmJob!=='bridge'){
    const plankKeep=deep?2:10;let nPlank=0;
    while(bridgePlanks.length>plankKeep){removePlankRecord(bridgePlanks[0]);cleaned++;nPlank++;}
    if(nPlank)parts.push(nPlank+' stray planks');
  }

  const floraKeep=Math.floor(FLORA_MAX*(deep?.82:.92));
  if(flora.length>floraKeep){
    const n=flora.length-floraKeep;flora.splice(0,n);cleaned+=n;parts.push(n+' overgrown sprouts');
  }

  markShadowDirty(2);saveDreams();
  updateStatus();
  if(!cleaned)return {ok:false,message:'The sandbox is already spotless.',
    thought:'I checked every corner. Spotless.',speech:pick(['I checked every corner. Spotless! 🧹','Nothing to tidy. My tails are already neat.']),
    cleaned:0};

  stats.loomTidies++;renderQuests();
  burst(loom.position.clone().add(new THREE.Vector3(0,1.6,0)),0x67e8f9,22);
  const summary=parts.join(', ');
  return {ok:true,cleaned,message:'Tidied '+summary+'.',
    thought:`Tidied ${summary}. A clean sandbox dreams clearer.`,
    speech:pick([`Tidied ${summary}. Breathing room restored! 🧹`,`${summary} composted back into starlight. Much better.`,`I swept up ${summary}. The islands feel lighter already.`])};
}
function loomTend(index){
  const i=Number.isFinite(index)?index:0;
  const isl=islands[i]||islands[0];const b=biomeOf(i);
  if(!isl)return {ok:false,message:'No island to tend yet.'};
  const n=8;
  for(let k=0;k<n;k++)plantFlora(isl.x+rand(-isl.r*.85,isl.r*.85),isl.z+rand(-isl.r*.85,isl.r*.85),i,true);
  if(b){b.bio=Math.min(1,b.bio+0.18);b.moisture=Math.min(1,b.moisture+0.12);b.mood=Math.min(1,b.mood+0.2);b.lastSeen=Date.now();}
  burst(new THREE.Vector3(isl.x,groundY(isl.x,isl.z)+1.5,isl.z),0x4ade80,26);
  const nm=isoName[i]||('Isle '+i);
  return {ok:true,cleaned:n,islandName:nm,message:`Tended ${nm} with ${n} glow-seeds.`,
    thought:`Watered ${nm} with starlight. Its glow is coming back.`,
    speech:pick([`I planted ${n} glow-seeds on ${nm}. Its bio-glow is waking up. 🌿`,`${nm} felt dim, so I tucked it in with new sprouts.`,`Tended ${nm}. The whole island exhaled.`]),
    xp:4};
}
function loomScout(index){
  const i=Number.isFinite(index)?index:0;
  const isl=islands[i]||islands[0];
  if(!isl)return {ok:false,message:'No island to scout yet.'};
  const x=isl.x+rand(-isl.r*.45,isl.r*.45),z=isl.z+rand(-isl.r*.45,isl.r*.45);
  loomRoam={x,z,until:performance.now()+6500,island:i};
  for(let k=0;k<5;k++)plantFlora(isl.x+rand(-isl.r*.8,isl.r*.8),isl.z+rand(-isl.r*.8,isl.r*.8),i,true);
  burst(new THREE.Vector3(x,groundY(x,z)+1.2,z),0x67e8f9,20);
  const nm=isoName[i]||('Isle '+i);
  return {ok:true,islandName:nm,message:`Scouted ${nm} and planted 5 trail-seeds.`,
    thought:`Scouting ${nm} on soft paws.`,
    speech:pick([`Scouting ${nm}! My nose says there's something new here. 🧭`,`A quick patrol of ${nm}. I left five little seeds behind.`,`Soft paws, sharp eyes. ${nm} looks full of possibility.`]),
    xp:5};
}
function loomSwarm(payload={}){
  const job=payload.job||'harvest';
  if(boids.length<4)deploySwarm(4);
  setSwarmJob(job);
  return {ok:true,job,message:`Put ${boids.length} Loomings on ${job} duty.`,
    thought:`The Loomings are on ${job} duty.`,
    speech:pick([`Loomings, ${job} formation! 🐝`,`I sent the swarm to ${job}. They love a job.`,`The Loomings are humming — ${job} duty.`])};
}
function loomDreamNow(payload={}){
  const res=doDream(payload.word||'wild dream orb',true);
  if(!res)return {ok:false,message:'Not enough dream-ink for an autonomous dream.'};
  return {ok:true,message:`Dreamed ${payload.name||'a new dream'}.`,
    thought:`Weaving ${payload.icon||'✨'} ${payload.name||'a dream'} into the sandbox.`,
    icon:payload.icon||'💭'};
}
function loomExcavateNow(){
  const f=canExcavate();
  if(!f)return {ok:false,message:'No island has decayed far enough to excavate yet.'};
  if(ink<12)return {ok:false,message:'Need 12 ✨ ink to excavate a memory.'};
  excavate();
  return {ok:true,message:'Excavated an ancient seal.',
    thought:'Digging up a memory the sand remembers.',
    islandName:isoName[biomes.indexOf(f.b)]||('Isle '+biomes.indexOf(f.b)),
    xp:0};
}
function lowestIsland(){
  let best=null;
  biomes.forEach((b,i)=>{if(!islands[i])return;
    const score=b.bio*0.75+b.mood*0.15+(b.visit?0.1:0)+b.stage*0.04;
    if(!best||score<best.score)best={i,score,b};});
  return best;
}
function buildLoomContext(){
  const catalog=DREAM_LIBRARY.map(d=>{
    const parsed=parseDream(d.word);
    return Object.assign({},d,{cost:Math.max(3,parsed.ink-discountFor(parsed.fn)),discovered:!!discovered[d.fn]});
  });
  const clutter=measureClutter();
  const low=lowestIsland();
  const seenTypes=Object.keys(discovered).length;
  return {
    running:$('#intro').classList.contains('hide'),
    ink,maxInk,night,
    idle:(performance.now()-lastPlayerTouch)/1000,
    bioAvg:bioAvg(),
    canExcavate:!!canExcavate(),
    boids:boids.length,swarmJob,
    catalog,
    dreamFloor:Math.max(16,hasSkill('skyweave')?18:22),
    dreamInterval:autoIntervalMs()/1000,
    clutter,
    lowIsland:low?low.i:0,
    playerIsland:nearestIsland(player.position.x,player.position.z).i,
    discoveredRatio:seenTypes/DREAM_LIBRARY.length
