}
function applyLoomResult(r){
  if(!r)return;
  if(r.speech)say(r.speech);
  if(r.log)logDream(r.log);
  if(r.toast)toast(r.toast);
  if(r.xp)gainXP(r.xp,'Loom autonomy');
}
