+}
+function removePlankRecord(b){
+  if(!b||!b.mesh)return false;
+  const m=b.mesh;
+  m.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material&&o.material.dispose)o.material.dispose();});
+  dreamGroup.remove(m);
+  const i=selectable.indexOf(m);if(i>-1)selectable.splice(i,1);
